mapper.select:
SELECT , (SELECT m.model_name FROM bt_library_large_model m WHERE m.model_id = b.model_id and m.tenant_id in (#{tenantId}, -1)) as "modelName" FROM bt_prompt_content b WHERE b.status_cd = '00A' AND b.tenant_id = #{tenantId}
AND b.prompt_id in ( #{promptId} )
AND b.model_id = #{modelId}

select bpc.messages
from bt_prompt_commit bpc
       join bt_prompt_basic bpb on bpc.prompt_id = bpb.id and bpb.latest_version = bpc.version
where bpb.id = #{promptId}
  and bpb.space_id = #{tenantId}

SELECT COALESCE(b.prompt_content, a.prompt_content)
FROM bt_prompt a
LEFT JOIN bt_prompt_content b ON b.tenant_id = a.tenant_id AND b.prompt_id = a.prompt_id AND b.model_id = #{modelId} AND b.status_cd = '00A'
LEFT JOIN bt_catalog c ON a.catalog_item_id = c.catalog_id and a.tenant_id = c.tenant_id
WHERE a.status_cd = '00A'
  AND a.tenant_id = #{tenantId}
  AND a.prompt_title LIKE

  #{title}

  AND c.catalog_name = #{catalogName}
